+// SPDX-License-Identifier: Apache-2.0
+
+use fsl_core::{FsResolver, parse_kernel_source};
+
+#[test]
+fn reviewgraphen_generated_regression() {
+    let source = r#"business Workflow {
+  actor Clerk
+  entity Case
+  process Case {
+    stages Open, Closed
+    initial Open
+    transition close Open -> Missing by Clerk
+  }
+}
+verify { instances Case = 1 }
+"#;
+    let Err(error) = parse_kernel_source(source, &FsResolver::new(".")) else {
+        panic!("an undeclared transition target must be rejected");
+    };
+    assert!(
+        error
+            .message
+            .contains("transition 'close' targets unknown stage 'Missing'"),
+        "unexpected error: {error:?}"
+    );
+}
